import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.B8TleWq7.js";const g=JSON.parse('{"title":"Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"guides/conventions.md","filePath":"guides/conventions.md"}'),r={name:"guides/conventions.md"};function i(s,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h1><p>The rules every Keel module follows. They are also the rules for game code written on top of Keel.</p><h2 id="module-headers" tabindex="-1">Module headers <a class="header-anchor" href="#module-headers" aria-label="Permalink to &quot;Module headers&quot;">​</a></h2><p>Every module starts with a header comment:</p><ul><li>a one-line summary;</li><li><strong>What it&#39;s for:</strong> a sentence or two in plain words on the problem it solves;</li><li>what it <strong>owns</strong>, who <strong>calls</strong> it, and what it <strong>fires</strong>;</li><li>then how to use it and the behaviour to rely on.</li></ul><p>The <a href="/Keel-Docs/api/">API Reference</a> is generated from these headers, so a good header is good documentation.</p><h2 id="reuse-before-writing" tabindex="-1">Reuse before writing <a class="header-anchor" href="#reuse-before-writing" aria-label="Permalink to &quot;Reuse before writing&quot;">​</a></h2><p>Before writing a helper, a check or a small utility, look in the <a href="/Keel-Docs/reference/cheat-sheet">cheat sheet</a>. If something there does the job (or nearly), use or extend it in its one home. Never write a second copy. When you add a shared building block, add its row there.</p><h2 id="code-rules" tabindex="-1">Code rules <a class="header-anchor" href="#code-rules" aria-label="Permalink to &quot;Code rules&quot;">​</a></h2><ul><li><strong>Split a file once it passes about 600 lines.</strong></li><li><strong>Tunable numbers live in Defs</strong>, never inside logic.</li><li><strong>Keel is never edited inside a game.</strong> Fix it in the Keel repo, bump the version, and update the game.</li><li><strong>No leftovers</strong> named <code>_Old</code>, <code>Backup</code> or <code>Removed*</code>. Git keeps the history.</li><li><strong>Ids are permanent.</strong> Defs ids and component names are saved and sent; never rename one.</li><li><strong>Init must not wait.</strong> Put waiting work in <code>Start</code>, or in <code>task.spawn</code>.</li><li><strong>Always write player state through <code>Replica.Set</code>.</strong> A direct write to the table is not sent to clients.</li><li><strong>Handlers still check game rules</strong> (ownership, distance, cooldowns). Net only guarantees shape and rate.</li></ul><h2 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to &quot;Naming&quot;">​</a></h2><ul><li>Services and Controllers return a table with a <code>Name</code> equal to the file name. The Loader warns if they differ.</li><li>Network messages are named <code>Feature.Action</code> (<code>Shop.Buy</code>).</li><li>Entity ids are never derived from an Instance name; a player is <code>player_&lt;UserId&gt;</code>.</li><li>Defs ids are lowercase letters, digits and <code>_</code>, starting with a letter (<code>sword_iron</code>).</li><li>Log tags match the module name: <code>Log.new(&quot;ShopService&quot;)</code>.</li></ul><h2 id="strictness" tabindex="-1">Strictness <a class="header-anchor" href="#strictness" aria-label="Permalink to &quot;Strictness&quot;">​</a></h2><p>Keel is <code>--!strict</code>. Vendored libraries are the only exception: each gets <code>--!nocheck</code> and <code>--!nolint</code> as its first two lines and is never edited otherwise. See <a href="/Keel-Docs/guides/tooling#vendored-libraries">Tooling and hooks</a>.</p>',14)])])}const m=o(r,[["render",i]]);export{g as __pageData,m as default};
